"""Tracks per-job timing and batch success metrics."""
import time

import config


class JobMetrics:
    def __init__(self, job_id):
        self.job_id = job_id
        self._start = None
        self._end = None
        self.succeeded = False

    def start(self):
        self._start = time.monotonic()

    def stop(self, succeeded):
        self._end = time.monotonic()
        self.succeeded = succeeded

    @property
    def duration_seconds(self):
        if self._start is None or self._end is None:
            return 0.0
        return self._end - self._start

    def exceeded_timeout(self):
        timeout_seconds = config.JOB_TIMEOUT_MS / 1000
        return self.duration_seconds > timeout_seconds


def summarize_batch(job_metrics):
    total = len(job_metrics)
    if total == 0:
        return 1.0
    succeeded = sum(1 for m in job_metrics if m.succeeded)
    success_rate = succeeded / total
    return success_rate


def meets_sla(job_metrics):
    return summarize_batch(job_metrics) >= config.SLA_SUCCESS_THRESHOLD

"""Uploads transcoded output files to remote storage in bandwidth-limited chunks."""
import time

import config


def _read_chunks(file_obj, chunk_size_bytes):
    while True:
        data = file_obj.read(chunk_size_bytes)
        if not data:
            break
        yield data


def wait_for_bandwidth(chunk_size_bytes, rate_kbps):
    if rate_kbps <= 0:
        return
    delay_seconds = chunk_size_bytes / rate_kbps
    time.sleep(delay_seconds)


def send_chunk(chunk, rate_kbps, sink):
    wait_for_bandwidth(len(chunk), rate_kbps)
    sink.write(chunk)


def upload_file(job, sink):
    chunk_size_bytes = config.CHUNK_SIZE_KB * 1024
    bytes_sent = 0
    with open(job.local_path, "rb") as f:
        for chunk in _read_chunks(f, chunk_size_bytes):
            send_chunk(chunk, config.BANDWIDTH_LIMIT_KBPS, sink)
            bytes_sent += len(chunk)
    return bytes_sent

"""Coordinates transcode upload jobs for a batch and reports on SLA compliance."""
from dataclasses import dataclass

import config
import metrics
import scheduler


@dataclass
class UploadJob:
    job_id: str
    local_path: str


def build_jobs(paths):
    return [UploadJob(job_id=f"job-{i}", local_path=p) for i, p in enumerate(paths)]


def process_batch(jobs):
    job_metrics = []
    for job in jobs:
        result = scheduler.run_job(job)
        job_metrics.append(result)
        if result.exceeded_timeout():
            print(f"{job.job_id} exceeded the configured timeout")
    return job_metrics


def report(job_metrics):
    success_rate = metrics.summarize_batch(job_metrics)
    print(f"batch success rate: {success_rate:.2%}")
    if metrics.meets_sla(job_metrics):
        print("batch meets SLA target")
    else:
        print("batch failed to meet SLA target")


def main(paths):
    jobs = build_jobs(paths)
    job_metrics = process_batch(jobs)
    report(job_metrics)


if __name__ == "__main__":
    import sys
    main(sys.argv[1:])
